import base64, hashlib, json, os, re, sys, types
from datetime import datetime, timezone
from pathlib import Path
import psycopg
source = base64.b64decode('')
module = types.ModuleType('hr_inventory_e')
sys.modules[module.__name__] = module
exec(compile(source, '<reviewed_hr_inventory>', 'exec'), module.__dict__)
try:
    dsn = Path(os.environ['PLATFORM_CONTROL_DATABASE_URL_FILE']).read_text().strip()
    def connect():
        return psycopg.connect(dsn, connect_timeout=5,
            options='-c default_transaction_read_only=on -c statement_timeout=15000 -c lock_timeout=2000')
    report = module.run_inventory(connect)
    with connect() as connection:
        readonly = connection.execute('SHOW transaction_read_only').fetchone()[0]
        role = connection.execute('SELECT current_user').fetchone()[0]
        rows = connection.execute('SELECT version,sha256 FROM platform_control.schema_migrations ORDER BY version').fetchall()
        migrations = [{'version': int(v), 'sha256': sha if isinstance(sha,str) and re.fullmatch('[0-9a-f]{64}',sha) else None} for v,sha in rows]
        connection.rollback()
    release = os.environ.get('PLATFORM_RELEASE_SHA','')
    output = {'observed_at': datetime.now(timezone.utc).isoformat(),
        'environment': 'production_platform_api', 'query_source_sha256': hashlib.sha256(source).hexdigest(),
        'release_sha': release if re.fullmatch('[0-9a-f]{40}',release) else None,
        'metadata_transaction_read_only': readonly == 'on',
        'app_identity_verified': role == 'platform_control_app',
        'migrations': migrations, 'inventory': report}
    print(json.dumps(output, ensure_ascii=False, sort_keys=True, indent=2))
except Exception:
    print(json.dumps({'capture_failed': True}))
    raise SystemExit(1)
